from playwright.sync_api import sync_playwright
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_context(viewport={"width":1500,"height":1000}).new_page(); errs=[]; pg.on("pageerror", lambda e: errs.append(str(e)))
    pg.on("dialog", lambda d: d.accept("matte gunmetal") if d.type == "prompt" else d.accept())
    pg.goto("http://localhost:4173/", wait_until="networkidle"); pg.wait_for_timeout(400)
    pg.click("#side .rail button[title='Generate']"); pg.wait_for_timeout(800)
    P = "#side .panel.active "
    pg.select_option(P+"select[title='Armour colour']", "dark green"); pg.select_option(P+"select[title='Armour type']", "power armor")
    pg.select_option(P+"select[title='Accent colour']", "red"); pg.select_option(P+"select[title='Helmet']", "off")
    pg.select_option(P+"select[title='Render style']", "semi")
    pg.fill(P+"textarea[placeholder^='segmented']", "segmented shoulder plates, exposed hydraulic joints"); pg.wait_for_timeout(100)
    pg.fill(P+"textarea[placeholder^='cyberpunk']", "cyberpunk, worn industrial"); pg.wait_for_timeout(100)
    pg.click(P+"button.tag[title='1boy']"); pg.fill(P+"input[type=search]", "running"); pg.wait_for_timeout(150); pg.click(P+"button.tag[title='running']"); pg.fill(P+"input[type=search]", ""); pg.wait_for_timeout(150)
    pg.evaluate("() => { const cb = [...document.querySelectorAll('#side .panel.active input[type=checkbox]')].find(c => c.title === 'LoRA studio-house-style'); cb.click(); }"); pg.wait_for_timeout(600)
    print("sent:", pg.evaluate("() => [...document.querySelectorAll('#side .panel.active p.mono')].map(p => p.textContent).find(t => t.startsWith('Sent as'))"))
    print("tokens:", pg.evaluate("() => document.querySelector('#side .panel.active [data-tokens]').textContent"))
    # custom colour via prompt dialog
    pg.select_option(P+"select[title='Clothing colour']", "__custom"); pg.wait_for_timeout(200)
    print("custom:", pg.evaluate("() => JSON.parse(localStorage.getItem('omni.ml')).design.clothingColour"))
    pg.evaluate("() => { const cb = [...document.querySelectorAll('#side .panel.active input[type=checkbox]')].find(c => c.title === 'Fast preview'); cb.click(); }"); pg.wait_for_timeout(200)
    pg.click(P+"button[title='Generate']"); pg.wait_for_timeout(2500)
    print("job:", pg.evaluate("() => { const j = window.omni.ml.jobs[0]; return [j.status, j.req.fast, j.result && j.result.fast, j.req.prompt.slice(0, 90), j.req.negative]; }"))
    print("preview chip:", pg.evaluate("() => !!document.querySelector('#side .panel.active .gen-job .chip.warn')"), "full btn:", pg.evaluate("() => !!document.querySelector(\"#side .panel.active button[title='Full quality']\")"))
    pg.click(P+"button[title='Full quality']"); pg.wait_for_timeout(2500)
    print("rerun:", pg.evaluate("() => { const j = window.omni.ml.jobs[0]; return [j.status, j.req.fast, j.req.steps, j.req.seed === window.omni.ml.jobs[1].req.seed]; }"))
    pg.evaluate("() => { const s = JSON.parse(localStorage.getItem('omni.ml')); s.guidance = 12; s.fast = false; localStorage.setItem('omni.ml', JSON.stringify(s)); }"); pg.reload(wait_until="networkidle"); pg.wait_for_timeout(600); pg.click("#side .rail button[title='Generate']"); pg.wait_for_timeout(600)
    print("guidance warn:", pg.evaluate("() => !!document.querySelector(\"#side .panel.active button[title='Use 7']\")"))
    pg.screenshot(path="design_panel.png", clip={"x": 1100, "y": 0, "width": 400, "height": 1000})
    print("errors:", errs)
    b.close()
